The cache needs two orderings: the lowest frequency first, and the oldest key when frequencies are equal. I keep one doubly linked list for each frequency. A hash map points from each key to its node, so the node can move between lists without searching.

The front of a list is the newest key. The back is the one to remove. `minFrequency` tells us which list to use when the cache is full.

```cpp
#include <unordered_map>
using namespace std;

class LFUCache {
private:
    struct Node {
        int key;
        int value;
        int frequency;
        Node* previous;
        Node* next;

        Node(int key, int value, int frequency = 1)
            : key(key), value(value), frequency(frequency),
              previous(nullptr), next(nullptr) {}
    };

    struct FrequencyList {
        Node* head;
        Node* tail;
        int size;

        FrequencyList() : size(0) {
            head = new Node(0, 0);
            tail = new Node(0, 0);
            head->next = tail;
            tail->previous = head;
        }

        void addToFront(Node* node) {
            node->next = head->next;
            node->previous = head;
            head->next->previous = node;
            head->next = node;
            size++;
        }

        void remove(Node* node) {
            node->previous->next = node->next;
            node->next->previous = node->previous;
            size--;
        }

        Node* removeLeastRecent() {
            if (size == 0) return nullptr;
            Node* node = tail->previous;
            remove(node);
            return node;
        }
    };

    int capacity;
    int minFrequency;
    unordered_map<int, Node*> nodes;
    unordered_map<int, FrequencyList*> lists;

    void increaseFrequency(Node* node) {
        int oldFrequency = node->frequency;
        FrequencyList* oldList = lists[oldFrequency];
        oldList->remove(node);

        if (oldFrequency == minFrequency && oldList->size == 0) {
            minFrequency++;
        }

        node->frequency++;
        if (!lists.count(node->frequency)) {
            lists[node->frequency] = new FrequencyList();
        }
        lists[node->frequency]->addToFront(node);
    }

public:
    LFUCache(int capacity) : capacity(capacity), minFrequency(0) {}

    int get(int key) {
        if (!nodes.count(key)) return -1;

        Node* node = nodes[key];
        int result = node->value;
        increaseFrequency(node);
        return result;
    }

    void put(int key, int value) {
        if (capacity == 0) return;

        if (nodes.count(key)) {
            Node* node = nodes[key];
            node->value = value;
            increaseFrequency(node);
            return;
        }

        if (static_cast<int>(nodes.size()) == capacity) {
            Node* removed = lists[minFrequency]->removeLeastRecent();
            nodes.erase(removed->key);
            delete removed;
        }

        Node* node = new Node(key, value);
        nodes[key] = node;
        if (!lists.count(1)) {
            lists[1] = new FrequencyList();
        }
        lists[1]->addToFront(node);
        minFrequency = 1;
    }
};
```

For example, with capacity 2, after `put(1, 10)`, `put(2, 20)`, and `get(1)`, key 1 moves to frequency 2. A later `put(3, 30)` removes key 2 because it is still in the minimum frequency list.

Time complexity: `O(1)` average for `get` and `put`.
Space complexity: `O(capacity)`. The input values are stored in linked nodes, so the cache owns extra node objects.

A `LinkedHashSet` is handy here because it gives fast removal by key and keeps insertion order. The map named `values` stores the value and frequency for every key. Another map stores the keys grouped by frequency.

The first key in the set with the smallest frequency is the least recently used one in that group. Whenever a key is read or updated, it is removed from its old set and added to the next set.

```java
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;

class LFUCache {
    private static class Entry {
        int value;
        int frequency;

        Entry(int value) {
            this.value = value;
            this.frequency = 1;
        }
    }

    private final int capacity;
    private int minFrequency;
    private final Map<Integer, Entry> values;
    private final Map<Integer, LinkedHashSet<Integer>> keysByFrequency;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.minFrequency = 0;
        this.values = new HashMap<>();
        this.keysByFrequency = new HashMap<>();
    }

    public int get(int key) {
        if (!values.containsKey(key)) {
            return -1;
        }

        Entry entry = values.get(key);
        moveToNextFrequency(key, entry);
        return entry.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) {
            return;
        }

        if (values.containsKey(key)) {
            Entry entry = values.get(key);
            entry.value = value;
            moveToNextFrequency(key, entry);
            return;
        }

        if (values.size() == capacity) {
            LinkedHashSet<Integer> leastUsed = keysByFrequency.get(minFrequency);
            int keyToRemove = leastUsed.iterator().next();
            leastUsed.remove(keyToRemove);
            values.remove(keyToRemove);
        }

        values.put(key, new Entry(value));
        keysByFrequency.computeIfAbsent(1, ignored -> new LinkedHashSet<>())
                       .add(key);
        minFrequency = 1;
    }

    private void moveToNextFrequency(int key, Entry entry) {
        int oldFrequency = entry.frequency;
        LinkedHashSet<Integer> oldKeys = keysByFrequency.get(oldFrequency);
        oldKeys.remove(key);

        if (oldFrequency == minFrequency && oldKeys.isEmpty()) {
            minFrequency++;
        }

        entry.frequency++;
        keysByFrequency.computeIfAbsent(entry.frequency,
                                        ignored -> new LinkedHashSet<>())
                       .add(key);
    }
}
```

A zero-capacity cache returns immediately from `put`, and a missing key returns `-1` from `get`. Updating an existing key also increases its frequency, as required by the cache operations.

Small dry run with capacity 2:

1. Add keys 1 and 2. Both are in frequency 1, with 1 older than 2.
2. Call `get(1)`. Key 1 moves to frequency 2.
3. Add key 3. Key 2 is removed because frequency 1 is lower than frequency 2.

Each hash lookup and `LinkedHashSet` operation takes `O(1)` average time. The space usage is `O(capacity)`.

This version keeps every entry in a priority queue ordered by frequency and then by the time it was last used. The first queue item is the eviction candidate.

It is shorter than maintaining linked lists, but there is a trade-off: Java's `PriorityQueue.remove(entry)` searches for an arbitrary entry, so updating an existing key is not constant time. This is useful when the cache is small or when simpler code matters more than the strict target complexity.

```java
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class LFUCache {
    private static class Entry {
        int key;
        int value;
        int frequency;
        long lastUsed;

        Entry(int key, int value, int frequency, long lastUsed) {
            this.key = key;
            this.value = value;
            this.frequency = frequency;
            this.lastUsed = lastUsed;
        }
    }

    private final int capacity;
    private long clock;
    private final Map<Integer, Entry> entries;
    private final PriorityQueue<Entry> queue;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.clock = 0;
        this.entries = new HashMap<>();
        this.queue = new PriorityQueue<>((a, b) -> {
            if (a.frequency != b.frequency) {
                return Integer.compare(a.frequency, b.frequency);
            }
            return Long.compare(a.lastUsed, b.lastUsed);
        });
    }

    public int get(int key) {
        Entry entry = entries.get(key);
        if (entry == null) {
            return -1;
        }

        queue.remove(entry);
        entry.frequency++;
        entry.lastUsed = clock++;
        queue.offer(entry);
        return entry.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) {
            return;
        }

        Entry existing = entries.get(key);
        if (existing != null) {
            queue.remove(existing);
            existing.value = value;
            existing.frequency++;
            existing.lastUsed = clock++;
            queue.offer(existing);
            return;
        }

        if (entries.size() == capacity) {
            Entry removed = queue.poll();
            entries.remove(removed.key);
        }

        Entry added = new Entry(key, value, 1, clock++);
        entries.put(key, added);
        queue.offer(added);
    }
}
```

A missing `get` returns `-1`. The zero-capacity check prevents polling from an empty queue. The timestamp is a `long`, so it will not overflow quickly during a normal run.

For example, if keys 4 and 5 both have frequency 2, the one with the smaller `lastUsed` value is removed first. If their frequencies differ, the lower frequency always wins.

`get` and updating an existing key take `O(capacity)` because of `PriorityQueue.remove`. Adding or evicting a new key costs `O(log capacity)`. Space complexity is `O(capacity)`.

Instead of keeping a separate linked list for every frequency, this version stores one ordered set. Each set item is `(frequency, time, key)`. The set sorts by frequency first and by access time second, so its first item is always the correct key to evict.

The map holds the current value and frequency for each key. Before changing an entry, its old tuple is erased from the set. A new key starts with frequency 1 and gets a fresh timestamp.

```cpp
#include <set>
#include <tuple>
#include <unordered_map>
using namespace std;

class LFUCache {
private:
    struct Entry {
        int value;
        int frequency;
        long long time;
    };

    int capacity;
    long long clock;
    unordered_map<int, Entry> entries;
    set<tuple<int, long long, int>> order;

public:
    LFUCache(int capacity) : capacity(capacity), clock(0) {}

    int get(int key) {
        auto found = entries.find(key);
        if (found == entries.end()) {
            return -1;
        }

        Entry& entry = found->second;
        order.erase({entry.frequency, entry.time, key});
        entry.frequency++;
        entry.time = clock++;
        order.insert({entry.frequency, entry.time, key});
        return entry.value;
    }

    void put(int key, int value) {
        if (capacity == 0) {
            return;
        }

        auto found = entries.find(key);
        if (found != entries.end()) {
            Entry& entry = found->second;
            order.erase({entry.frequency, entry.time, key});
            entry.value = value;
            entry.frequency++;
            entry.time = clock++;
            order.insert({entry.frequency, entry.time, key});
            return;
        }

        if (static_cast<int>(entries.size()) == capacity) {
            auto first = order.begin();
            int keyToRemove = get<2>(*first);
            order.erase(first);
            entries.erase(keyToRemove);
        }

        Entry entry{value, 1, clock++};
        entries[key] = entry;
        order.insert({entry.frequency, entry.time, key});
    }
};
```

The set handles both eviction rules in one place. For equal frequencies, the smaller timestamp means an older access, so that key is selected first. Updating an existing key counts as another use and changes its value as well.

A cache with capacity 0 is the main special case. Also, `get` never inserts a missing key.

The set operations make both methods `O(log capacity)` average time. The hash map and ordered set together use `O(capacity)` space.

