class List
{
public:
    Node *head , *tail;
    int size;

    List()
    {
        head = new Node(-1,-1);
        tail = new Node(-1,-1);
        head->next = tail;
        tail->prev = head;
        size = 0;
    }

    void RemoveFromList(Node *temp)
    {
        temp->prev->next = temp->next;
        temp->next->prev = temp->prev;
        size--;
    }

    void AddtoList(Node *temp)
    {
        temp->prev = head;
        temp->next = head->next;
        head->next = temp;
        temp->next->prev = temp;
        size++;
    }
};

