```cpp[]
/*
Note: 
-> There is 1 'LFUCache'
-> This 'LFUCache' contains multiple DLLs based on 'cnt' (i.e. frequency) value
-> Each DLL is a 'List' of multiple 'Node' s.
-------------------------------------------------------------------------------
-> 'cnt' (i.e. frequency) means, # of times operations(get/put) were done over this 'key'
-> If two nodes have same frequency, then tie will be broken by LRU
*/

//A node inside the DLL
class Node
{
    public:
    Node* prev;
    int key;
    int val;
    int cnt; //frequency (# of get/put called over this node)
    Node* next;

    Node(int _key, int _val)
    {
        prev = nullptr;
        key = _key;
        val = _val;
        cnt = 1;
        next = nullptr;
    }
};

//A DLL
class List
{
    public:
    Node* head;
    Node* tail;
    int size;

    List()
    {
        head = new Node(0,0);
        tail = new Node(0,0);

        head->next = tail;
        tail->next = head;

        size = 0;
    }

    void isolateNode(Node* node)
    {
        node->prev->next = node->next;
        node->next->prev = node->prev;

        size--;
    }

    void insertAfterHead(Node* node)
    {
        Node* nextNode = head->next;

        head->next = node;
        node->prev = head;

        node->next = nextNode;
        nextNode->prev = node;

        size++;
    }
};

//An LFUCache (containing multiple DLLs, based upon frequency (or) 'cnt')
class LFUCache 
{
    private:
    map<int , Node*> nodes; //<key,Node*> :: All nodes 
    map<int , List*> lists; //<cnt,List*> :: Segregating different DLLs based upon 'cnt' i.e. frequency
    int cap;

    int currSize; //Stores current LFUCache size (# of Node)
    int minCnt;   //Stores 'cnt' value of least frequently used node

    public:
    LFUCache(int _cap)  
    {   
        nodes.clear();
        lists.clear();
        cap = _cap;

        currSize = 0;
        minCnt = 0;
    }

    void update_node_lists_nodes(Node* node)
    {
        //This node's 'cnt' value has been increased by 1

        List* lst = lists[node->cnt];   //Pointer to the 'List' to which this 'node' belongs
        lst->isolateNode(node);         //Isolate this 'node'

        // If node was the last node having it's frequency => Update the minimum frequency
        if( (node->cnt == minCnt) && (lists[node->cnt]->size == 0) ) 
           minCnt++; 

        //If the next higher frequency List doen't exist => Create dummy List for this frequency
        //Else just assign the List& of already existent List having frequency 'cnt+1'

        List* higherList;  //List with frequency of 'cnt+1'
        if(lists.find(node->cnt + 1) == lists.end())
            higherList = new List();
        else
            higherList = lists[node->cnt + 1];


        //Now increment the 'cnt' in the 'Node' itself
        node->cnt++;

        //Add this 'Node' in front of 'higherList'
        higherList->insertAfterHead(node);

        //Update 'lists'
        lists[node->cnt] = higherList;
    }

    int get(int _key) 
    {
        if(nodes.find(_key) == nodes.end())
            return -1;

        Node* node = nodes[_key];
        int _val = node->val;

        //Update: 
        //1) This node's 'cnt' (using 'nodes' map)
        //2) The List* to which this node belongs (using 'lists' map)
        update_node_lists_nodes(node);

        return _val;
    }

    void put(int _key, int _val) 
    {
        //If cache size is zero => Nothing can be inserted
        if(cap == 0)
            return;

        //If key already exists
        if(nodes.find(_key) != nodes.end())
        {
            Node* node = nodes[_key];
            node->val = _val;

            update_node_lists_nodes(node);
        }
        //Else
        else
        {
            //If cache limit exceeds => First, a 'node' removal is required
            if(currSize == cap)
            {
                //Least-Frequently-Used 'node'
                List* lst = lists[minCnt];      //List having minimum 'cnt' value
                Node* node = lst->tail->prev;   //Node in this list, at the last

                lst->isolateNode(node);         //Isolate this 'node' from 'lst'
                nodes.erase(node->key);         //Remove it from 'nodes' (All-Nodes) map

                currSize--;                     //Decrement cache current-size
            }

            //Now insert this new 'node' with 'cnt' 1
            currSize++;
            minCnt = 1;

            List* newList;
            if(lists.find(1) == lists.end())
                newList = new List();
            else
                newList = lists[1];

            Node* newNode = new Node(_key, _val);
            newList->insertAfterHead(newNode);
            nodes[_key] = newNode;
            lists[1] = newList;
        }
    }
};

